/* Esperanto Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ludoviko": "Zamenhof's own Esperanto name: Ludwik Zamenhof became Ludoviko.", "Klara": "bright, clear — Latin clara", "Johano": "God is gracious — Hebrew, Esperantized", "Mario": "Mary rendered in Esperanto spelling.", "Petro": "rock, stone — Greek, Esperantized", "Doktoro Esperanto": "Doctor Hopeful — Esperanto espero (hope)", "Zamenhof": "Ludwik Lejzer Zamenhof, creator of Esperanto, born in Bialystok.", "Privat": "Edmond Privat, the great Esperanto author and activist.", "Waringhien": "Gaston Waringhien, the great Esperanto grammarian.", "Kalocsay": "Kalman Kalocsay, the great Esperanto poet."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ludoviko';
console.log(lookup(q));

